/**
 * create the chatGPT question
 * @param {string} GPTNodesStructure - nodes in the form of Chat GPT Structure
 * @param {string} researchQuestion 
 * @returns a string ready for OpenAI to ingest 
 */
async function createPrompt(GPTNodesStructure, researchQuestion) {
    console.log(`${_module}/createPrompt @params GPTNodesStructure length`, GPTNodesStructure.length)
    console.log(`${_module}/createPrompt @params researchQuestion`, researchQuestion)

    var question

    if (GPTNodesStructure.length == 0) {
        question = `Given the following research question: '${researchQuestion}' 
        Provide a comprehensive list of causal relationships related to the research question in the form of a DAG. Use graphviz minimal syntax for the DAG and use camelcase format for the node labels. 
        Suggest similar research questions considering counterfactual analysis and actual causality.
        `
    } else {
        question = `Given the following research question: '${researchQuestion}'
        and the following existing causal model (DAG) in the form [VariableA]-->[VariableB], 
        are there any other causal relationships that are relevant to the research question
        or anything that would affect the existing causal variables,
        consider multiple levels of relationships in your answer:\n\n
        Causal Model: ${GPTNodesStructure} \n\n
        Provide a comprehensive list of causal relationships related to the research question in the form of a DAG. Use graphviz minimal syntax for the DAG and use camelcase format for the node labels. 
        Suggest similar research questions considering counterfactual analysis and actual causality.
        `
    }
    console.log(`${_module}/createPrompt question`, question)
    return question
}

/**
 * format causal model ready for chatGPT, format [a] --> [b]
 * @param {object} nodes - 
 * @returns 
 */

async function createGPTNodeStructure(nodes) {
    try {
        console.log(`${_module}/createGPTNodeStructure`)
        console.log(`${_module}/createGPTNodeStructure @param nodes`, nodes)
        if (nodes === undefined) { return [] }
        // start by getting all the nodes without children
        var rightNodes = []
        var chatGPTOutput = ""
        nodes.forEach((node) => {
            if (!node.hasOwnProperty("wires")) {
                console.log(`${_module}/createGPTNodeStructure ${node.name} has no wires`)
                rightNodes.push(node)

            }
        })
        // recursive scan of nodes - right to left
        var leftNodes
        while (rightNodes.length > 0) {
            leftNodes = []
            rightNodes.forEach((rightNode) => {
                nodes.forEach((node) => {
                    // check against all nodes with wires
                    if (node.hasOwnProperty("wires")) {
                        if (
                            node.wires[0].filter((value) => rightNode.id.includes(value))
                                .length > 0
                        ) {
                            chatGPTOutput +=
                                "[" + node.name + "] --> [" + rightNode.name + "], "
                            leftNodes.push(node)
                        }
                    }
                })

            })
            rightNodes = leftNodes
        }

        return chatGPTOutput.replace(/,\s*$/, "") // remove trailing comma and whitespace
    } catch (exception) {
        throw exception
    }
}

/**
 * Load prompt for causal diagrams
 * @param {object} req - request object contains activeWorkspace, nodes, etc
 * @param {object} res - response object contains formulated prompt
 */
async function loadPrompt(req, res) {
    try {
        let prompt = ""
        if (req.body.activeWorkspace == 0) {
            res.status(200).send({ prompt: prompt })
            return
        } else {
            let nodes = req.body.nodes
            let researchQuestion = req.body.researchQuestion
            let prompt = ""
            let workspace = await getWorkspaceContext(req)
            console.log(`${_module}/loadPrompt workspace`, workspace)
            // let ctx = await runtime.causeway.getContext()
            // let previousResearchQuestion = ctx.get("gpt_research_question")
            let previousResearchQuestion = workspace["gpt_research_question"]
            if (previousResearchQuestion === undefined) { previousResearchQuestion = "" }
            console.log(`${_module}/loadPrompt`)
            console.log(`${_module}/loadPrompt @params activeWorkspace`, req.body.activeWorkspace)
            console.log(`${_module}/loadPrompt @params nodes`, nodes)
            console.log(`${_module}/loadPrompt @params researchQuestion`, researchQuestion)
            console.log(`${_module}/loadPrompt context previousResearchQuestion`, previousResearchQuestion)

            if (previousResearchQuestion.length > 0) {
                // check if new research question is different and if so create a new prompt else return old prompt
                if (previousResearchQuestion !== researchQuestion) {
                    workspace["gpt_research_question"] = researchQuestion
                    // ctx.set("gpt_research_question", researchQuestion)
                    prompt = await createGPTNodeStructure(nodes).then(async (gpt_res) => {
                        console.log(`${_module}/loadPrompt response `, gpt_res)
                        return await createPrompt(gpt_res, researchQuestion)
                    })
                } else {
                    let workspace = await getWorkspaceContext(req)
                    prompt = await getPrompt(workspace)
                }
            } else {
                workspace["gpt_research_question"] = researchQuestion
                // set research question in context
                // await ctx.set("gpt_research_question", researchQuestion)

                // create new prompt
                prompt = await createGPTNodeStructure(nodes).then(async (gpt_res) => {
                    console.log(`${_module}/loadPrompt response `, gpt_res)
                    return await createPrompt(gpt_res, researchQuestion)
                })
            }

            // update workspace with new prompt
            workspace["gpt_prompt"] = prompt
            // set context prompt to new prompt
            let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
            // await ctx.set(req.body.activeWorkspace, workspace)
            // await ctx.set("gpt_prompt", prompt)
            res.status(200).send({ prompt: prompt, updatedFlow: updatedFlow })
            return
        }
    } catch (exception) {
        console.log(`${_module} exception `, exception)
        res.status(500).send({ error: exception })
    }
}

