/**
 * 
 * @param {*} req 
 * @returns 
 */
async function getRecentResult(workspace, req) {
    try {
        console.log(`${_module} getRecentResult`, workspace)
        let gpt_recent = workspace.hasOwnProperty("gpt_recent_results") ? workspace["gpt_recent_results"] : []
        gpt_recent.forEach(async (cr_set) => {
            await cr_set.forEach(async (cr) => {
                let nodePairs = [...cr.label.split("->")]
                let cause = await nodePairs[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").trim().replaceAll(";", "")
                let effect = await nodePairs[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").trim().replaceAll(";", "")
                if (req.query.nn !== undefined) {
                    let causeId = req.query.nn.hasOwnProperty(cause) ? req.query.nn[cause] : undefined
                    let effectId = req.query.nn.hasOwnProperty(effect) ? req.query.nn[effect] : undefined
                    console.log(`${_module}/getRecentResults cause ${cause}, causeId ${causeId}, effect ${effect}, effectId ${effectId}\'`)
                    if (causeId !== undefined) {
                        let causeNode = runtime._.nodes.getNode(causeId)
                        let actuallyAdded = false
                        if (causeNode !== undefined && causeNode !== null) {
                            if (causeNode.wires !== undefined) {
                                causeNode.wires[0].forEach(wire => {
                                    if (wire === effectId) { actuallyAdded = true }
                                })
                            }
                            cr.sublabel = actuallyAdded ? "added" : ""
                        }
                    } else {
                        cr.sublabel = ""
                        cr.label = cause + "->" + effect
                    }
                } else {
                    cr.sublabel = ""
                    cr.label = cause + "->" + effect
                }
            })
        })
        return gpt_recent
    }
    catch (exception) {
        console.log(`${_module}/getRecentResults exception `, exception)
        return exception
    }
}

/**
 * Get prompt info 
 * @param {*} req 
 * @param {*} res 
 * @returns 
 */
async function getPromptInfo(req, res) {
    try {
        console.log(`${_module} getPromptInfo req `, req.query)
        // match typedb first 
        let match_gpt_info = `match $gpt_info isa gpt_info, has nrid \"${req.query.activeWorkspace}\"; get $gpt_info;`
        let opts = {
            "db": "causeway-repo",
            "query": match_gpt_info,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ"
        }
        let query_result = await typedbApi.executeQuery(opts)
        let items = await query_result.collect()
        let workspace = {}
        let researchQuestion = ""
        let prompt = ""
        let gpt_info = ["", ""]
        let recent_result = ""
        let keys = new Set(["gpt_research_question", "gpt_prompt", "gpt_recent_results", "gpt_api_key", "gpt_api_org"])
        if (items.length !== 0) {
            let _gpt_info = items[0].get("gpt_info").asRemote(await typedbApi.get_transaction(opts.transaction_type))
            let _gpt_info_attributes = await _gpt_info.getHas().collect()
            console.log(`${_module} [ gpt_info ] gpt_info`, _gpt_info)
            for await (let attribute of _gpt_info_attributes) {
                let _label = attribute.type.label.name
                let attr_value = attribute.value
                console.log(`${_module} [ gpt_info ] gpt_info_attribute label.name`, _label)
                console.log(`${_module} [ gpt_info ] gpt_info_attribute attr_value`, attr_value)
                if (keys.has(_label)) {
                    if (_label === "gpt_research_question") { researchQuestion = attr_value }
                    if (_label === "gpt_prompt") { prompt = attr_value }
                    if (_label === "gpt_recent_results") {
                        console.log(`${_module} [ gpt_info ] `, typeof attr_value)
                        attr_value = attr_value.replaceAll(/\'/g, "\"")
                        recent_result = await JSON.parse(attr_value)
                        for await (let result of recent_result[0]) {
                            console.log(result)
                            result.checkbox = true
                            result.selected = false
                            result.collapsible = true
                            console.log(result)
                        }
                        console.log(`${_module} [ gpt_info ] recent_result`, recent_result)
                    }
                    if (_label === "gpt_api_key") { gpt_info[0] = attr_value }
                    if (_label === "gpt_api_org") { gpt_info[0] = attr_value }
                }
            }
        } else {
            console.log(`${_module} [ gpt_info ] gpt_info does not exist`)
            workspace = await getWorkspaceContext(req)
            researchQuestion = await getResearchQuestion(workspace)
            prompt = await getPrompt(workspace)
            gpt_info = await getGPTInfo(workspace)
            recent_result = await getRecentResult(workspace, req)
        }
        await typedbApi.close_transaction(opts.transaction_type)
        res.status(200).send({ researchQuestion: researchQuestion, prompt: prompt, gptInfo: gpt_info, gpt_recent_results: recent_result })
        return
    } catch (exception) {
        console.log(`${_module} getResearchQuestion exception `, exception)
        res.status(500).send({ error: exception })
    }
}


/** 
 * process response from ChatGPT
 */
async function processGPTResponse(answer) {
    try {
        var nodePairSet = await answer.map(response => {
            let digraph = response.text.replaceAll("+", "").replaceAll("\'", "")
            // split digraph into sub array
            let substrings = digraph.split("\n")
            let nodes = {}
            let relations = new Set()
            if (substrings !== undefined) {
                substrings.forEach(string => {
                    // identify statement type
                    // node statement
                    if (string.includes("label")) {
                        console.log("Node statement: ", string)
                        let _node = string.split("[")
                        let node_id = _node[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        let label = _node[1]
                            .match(/(?:"[^"]*"|^[^"]*$)/)[0]
                        nodes[node_id] = label
                        console.log(nodes)
                    }
                    // edge 
                    if (string.includes("->")) {
                        console.log("Edge Statement", string)
                        let node_pair = string.split("->")
                        let cause = node_pair[0].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        let effect = node_pair[1].replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        if (effect.includes("label")) {
                            effect = effect.split("[")[0].replaceAll(" ", "")
                        }
                        let causeName = nodes[cause] ? nodes[cause] : cause
                        let effectName = nodes[effect] ? nodes[effect] : effect
                        console.log("\tcause in relation : ", causeName)
                        console.log("\teffect in relation ", effectName)

                        causeName = causeName.replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        effectName = effectName.replaceAll(/\s/g, '').replaceAll("_", "").replaceAll("\t", "").replaceAll("\n", "").replaceAll("\"", "").replaceAll(";", "").replaceAll(" ", "").trim()
                        relations.add(causeName + "-> " + effectName)
                    }
                })
            }
            console.log(`${_module} processGPTResponse relations`, relations)
            let nodePairs = Array.from(relations).map(relation => {
                // prepare item to be added to list as disction
                let node = {
                    "label": relation,
                    "checkbox": true, // (optional) if present, display checkbox accordingly
                    "selected": false, // (optional) whether the item is selected or not
                    "collapsible": true, // prevent a parent item from being collapsed. default true.
                    "sublabel": ""
                }
                return node
            })
            return nodePairs
        })
        console.log(`${_module} processGPTResponse nodePairSets `, nodePairSet)
        return nodePairSet
    } catch (exception) {
        console.log(`${_module} processGPTResponse exception `, exception)
        throw exception
    }
}

async function updateWorkspaceContext(id, workspace) {
    console.log(`${_module} updateWorkspaceContext `, id, workspace)
    let ctx = await runtime.causeway.getContext(id)
    let flow = runtime._.nodes.getFlow(id)
    if (flow === null || flow === undefined) { flow = {} }
    console.log(`${_module} updateWorkspaceContext flow keys`, Object.keys(flow))
    console.log(`${_module} updateWorkspaceContext workspace keys`, Object.keys(workspace))
    for await (let key of Object.keys(workspace)) {
        console.log(key)
        flow[key] = workspace[key]
    }
    await ctx.set(id, workspace)
    return flow

}
async function getOpenAIResponse(req, res) {
    try {
        var answer = ""
        let workspace = await getWorkspaceContext(req)
        if (!req.query.api_key.includes("...")) { workspace["gpt_api_key"] = req.query.api_key }
        if (!req.query.api_org.includes("...")) { workspace["gpt_api_org"] = req.query.api_org }
        console.log(`${_module} getOpenAIResponse workspace apikey`, workspace["gpt_api_key"])
        // set up configuration 
        const configuration = new Configuration({
            apiKey: workspace["gpt_api_key"],
            // organization: workspace["gpt_api_org"]
        })
        const openai = new OpenAIApi(configuration)
        console.log(`${_module} getOpenAIResponse  openai`, openai.configuration)
        let prompt = "You are an expert system of causal reasoning. \n"
        prompt += req.query.prompt
        console.log(`${_module} getOpenAIResponse newPrompt`, prompt)

        // submit the question to chatGPT
        const response = await openai.createCompletion({
            model: "text-davinci-003",
            prompt: prompt,
            n: 1,
            // stop: "\n",
            max_tokens: 575,
        })
        // const response = await openai.createCompletion({
        //     model: "text-davinci-003",
        //     prompt: "Say this is a test",
        //     max_tokens: 7,
        //     temperature: 0,
        // });

        var answer = response.data.choices
        console.log(`${_module} getOpenAIResponse answer`, answer)
        let processedAnswered = await processGPTResponse(answer)
        workspace["gpt_recent_results"] = processedAnswered
        let updatedFlow = await updateWorkspaceContext(req.query.activeWorkspace, workspace)

        // update the api key and cause discovery of the gpt info stored in typedb
        // disconnecting gpt_info from old api key
        // match $gpt_info isa gpt_info, has nrid "Medicely", has gpt_api_key $api_key; delete $gpt_info has $api_key; insert $gpt_info has api_key "81726354";
        let update_api_key = `match $gpt_info isa gpt_info, has nrid \"${req.query.activeWorkspace}\", has gpt_api_key $gpt_api_key; delete $gpt_info has $gpt_api_key; insert $gpt_info has gpt_api_key \"${workspace["gpt_api_key"]}\";`
        let opts = {
            "db": "causeway-repo",
            "query": update_api_key,
            "query_type": "update",
            "session_type": "DATA",
            "transaction_type": "WRITE"
        }
        await typedbApi.executeQuery(opts)
        // update response 

        let gpt_recent_results = JSON.stringify(workspace["gpt_recent_results"])
        gpt_recent_results = gpt_recent_results.replace(/"/g, "'")
        let update_recents_results = `match $gpt_info isa gpt_info, has nrid \"${req.query.activeWorkspace}\", has gpt_recent_results $gpt_recent_results; delete $gpt_info has $gpt_recent_results; insert $gpt_info has gpt_recent_results \"${gpt_recent_results}\";`
        opts = {
            "db": "causeway-repo",
            "query": update_recents_results,
            "query_type": "update",
            "session_type": "DATA",
            "transaction_type": "WRITE"
        }
        await typedbApi.executeQuery(opts)

        // disconnecting gpt_info from old api key
        // match $gpt_info isa gpt_info, has nrid "Medicely", has gpt_api_key $api_key; delete $gpt_info has $api_key; insert $gpt_info has api_key "81726354";

        delete configuration
        delete openai
        res.status(200).send({ gpt_results: processedAnswered, updatedFlow: updatedFlow })
        return
    } catch (error) {
        console.log(`${_module} getOpenAIResponse error`, error)
        return error
    }
}

