async function fixPosition(leftNode, rightNode, type, flow, linksToAdd) {
    console.log(`${_module} fixposition leftNode(x,y) ${leftNode.x}, ${leftNode.y} && rightNode (x,y) ${rightNode.x}, ${rightNode.y}`)
    // update right node x and y according to leftNode
    if (type) {
        rightNode.x = await getAxisValue(175, 200, leftNode.x)
        if (rightNode.x < 0) {
            rightNode.x = 50
        }
        let increment = 25
        // temporarily update left node wires
        leftNode.wires[0].push(rightNode.id)
        let wireLengths = 0
        await flow.nodes.forEach(node => {
            if (node.id === leftNode.id) {
                wireLengths = node.wires[0].length
            }
        })
        rightNode.y = wireLengths === 1 ? leftNode.y : await getAxisValue(50, increment * wireLengths - 1, leftNode.y)
        console.log(`${_module} fixposition  updated rightNode ${rightNode.x} ${rightNode.y}`)
    } else {
        leftNode.x = await getAxisValue(-250, -200, rightNode.x)
        if (leftNode.x < 0) {
            leftNode.x = 50
        }
        let increment = 25
        // temporarily update left node wires
        console.log(`${_module} fixposition  leftNode `, leftNode)
        let totalInputs = 0
        await flow.nodes.forEach(async (node) => {
            let wires = new Set(node.wires[0])
            if (wires.has(rightNode.id)) {
                totalInputs += 1
            }
        })
        // check all new links to add ot see if positioning needs readhjusting
        let findTotalInputs = async (linksToAdd, rightNode, totalInputs) => {
            console.log(`${_module} fixposition findTotalInputs  linksToAdd`, linksToAdd)
            console.log(`${_module} fixposition findTotalInputs  rightNode`, linksToAdd)
            console.log(`${_module} fixposition findTotalInputs  totalInputs`, totalInputs)
            Object.keys(linksToAdd).forEach(async (key) => {
                let wires = new Set(linksToAdd[key])
                if (wires.has(rightNode.id)) {
                    totalInputs += 1
                }
            })
            return totalInputs
        }
        totalInputs = await findTotalInputs(linksToAdd, rightNode, totalInputs)
        console.log(`${_module} fixposition totalInputs ${totalInputs} ${totalInputs - 1 === 0}`)
        leftNode.y = totalInputs - 1 === 0 ? rightNode.y : await getAxisValue(50, 50 + increment * totalInputs - 1, rightNode.y)
        console.log(`${_module} fixposition updated leftNode ${leftNode.x}, ${leftNode.y}`)
    }
}

async function addNewRelations(req, res) {
    try {
        let workspace = await getWorkspaceContext(req)
        let gpt_recent = workspace["gpt_recent_results"] ? workspace["gpt_recent_results"] : []
        let flow = await runtime._.nodes.getFlow(req.body.activeWorkspace)
        let flowId = flow.id ? flow.id : req.activeWorkspace
        let nn_exists = Object.keys(req.body).includes("nn")
        let nodesToAdd = []
        linksToAdd = {}
        let seenNodes = {}
        for await (let relation of req.body.newRelations) {
            relation = relation.split("->")
            let causeName = relation[0]
            let effectName = relation[1]
            let causeExists = false
            let effectExists = false
            let leftNode = {}
            let rightNode = {}
            let leftNodeId = ""
            let rightNodeId = ""
            if (nn_exists) {
                causeExists = req.body.nn[causeName] ? true : false
                leftNode = req.body.nn[causeName] ? req.body.nn[causeName] : leftNode
                effectExists = req.body.nn[effectName] ? true : false
                rightNode = req.body.nn[effectName] ? req.body.nn[effectName] : rightNode
            }
            console.log(`${_module} addNewRelations nodesToAdd.length ${nodesToAdd.length}`)

            for await (let node of nodesToAdd) {
                if (causeName === node.name) {
                    console.log("node previously added in this run")
                    leftNode = node
                    causeExists = true
                }
                if (effectName === node.name) {
                    console.log("effect node previously added in this run")
                    rightNode = node
                    effectExists = true
                }
            }
            console.log(`${_module} addNewRelations causeName ${causeName} ; causeExists ${causeExists}`)
            console.log(`${_module} addNewRelations effectName ${effectName} ; effectExists ${effectExists}`)
            if (causeExists && effectExists) {
                /**  do nothing */
                console.log(`${_module} addNewRelations [ both nodes exist]`)
                console.log(`${_module} addNewRelations leftNode ${leftNode} rightNode ${rightNode}`)

                if (linksToAdd.hasOwnProperty(leftNode)) {
                    let items = new Set(linksToAdd[leftNode])
                    if (!items.has(rightNode)) {
                        linksToAdd[leftNode].push(rightNode)
                    }
                } else {
                    linksToAdd[leftNode] = [rightNode]
                }
                console.log(`${_module} addNewRelations linksToAdd `, linksToAdd)
            } else if (causeExists) {
                /** 
                 * if the left node exists then
                 * (1) create the right node
                 * (2) update the left node by pushing the id of the right node to node wires
                 * (3) add the right node to the flow
                 * */
                // only cause node exists
                console.log(`${_module} addNewRelations [ only left node exists ]`)
                // get cause node 
                await flow.nodes.forEach(node => {
                    if (node.id === req.body.nn[causeName]) { leftNode = node }
                })
                //  (1) create rightNode
                rightNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: effectName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[]],
                }
                rightNode = await updateNode(rightNode)
                await fixPosition(leftNode, rightNode, true, flow, linksToAdd)

                // (2) find left node & update wires
                let causeNodeID = req.body.nn[causeName]

                // (3) add rightNode to flow
                nodesToAdd.push(rightNode)
                if (linksToAdd.hasOwnProperty(causeNodeID)) {
                    let items = new Set(linksToAdd[causeNodeID])
                    if (!items.has(rightNode.id)) {
                        linksToAdd[causeNodeID].push(rightNode.id)
                    }
                } else {
                    linksToAdd[causeNodeID] = [rightNode.id]
                }
                console.log(`${_module} addNewRelations [ only left node exists ] nodesToAdd ${nodesToAdd} linksToAdd ${linksToAdd}`)

            } else if (effectExists) {

                /** 
                 * if the right node exists then
                 * (1) create the left node and add to its wires the node red id
                 * (2) find the right node to update the left node x,y,and wires
                 * (3) add new left node to the flow's nodes
                 * */
                console.log(`${_module} addNewRelations [ only right node exists ]`)
                if (nn_exists) {
                    rightNodeId = req.body.nn.hasOwnProperty(effectName) ? req.body.nn[effectName] : rightNode.id
                } else {
                    rightNodeId = rightNode.id
                }

                //  (1) initialize left node using causeeffect json
                leftNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: causeName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[rightNodeId]],
                }
                // (2) iterate the the flows nodes to find right node and update the fields x,y, and wires of the leftnode
                await flow.nodes.forEach(async (node) => {
                    if (node.id === rightNodeId) {
                        rightNode = node
                    }
                })
                leftNode = await updateNode(leftNode)
                // (3) add left node to flow nodes
                nodesToAdd.push(leftNode)
                if (linksToAdd.hasOwnProperty(leftNode.id)) {
                    let items = new Set(linksToAdd[leftNode.id])
                    if (!items.has(rightNodeId)) {
                        linksToAdd[leftNode.id].push(rightNodeId)
                    }
                } else {
                    linksToAdd[leftNode.id] = [rightNodeId]
                }
                await fixPosition(leftNode, rightNode, false, flow, linksToAdd)

            } else if (!causeExists && !effectExists) {
                /** 
                  * if neither left or right node exists
                  * (1) initialize left node
                  * (2) initialize right node
                  * (3) update nodes' x,y, and wire fields with actual values
                  * (4) add nodes to the flow
                  * */

                console.log(`${_module} addNewRelations [ Neither node exists ]`)
                // (1) initialize leftNode
                leftNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: causeName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[]],
                }
                // (2) initialize rightNode
                rightNode = {
                    id: "",
                    type: "causeeffect",
                    z: flowId,
                    name: effectName,
                    props: [],
                    property: "attributes",
                    propertyType: "msg",
                    treatment: false,
                    outcome: false,
                    edgestrength: "",
                    causalmechanisms: "",
                    intrinsiceffects: "",
                    jsondigraph: "",
                    fx: "",
                    x: "",
                    y: "",
                    wires: [[]],
                }

                // (3) update nodes x,y, and wire fields with actual values
                rightNode = await updateNode(rightNode)
                leftNode = await updateNode(leftNode)

                // update right node 
                await fixPosition(leftNode, rightNode, true, flow, linksToAdd)

                //  (4) add nodes to the flow
                nodesToAdd.push(leftNode)
                nodesToAdd.push(rightNode)
                if (linksToAdd.hasOwnProperty(leftNode.id)) {
                    let items = new Set(linksToAdd[leftNode.id])
                    if (!items.has(rightNode.id)) {
                        linksToAdd[leftNode.id].push(rightNode.id)
                    }
                } else {
                    linksToAdd[leftNode.id] = [rightNode.id]
                }
            }

            // iterate through recent results to see if relation is added
            await gpt_recent.forEach(cr_set => {
                cr_set.forEach(cr => {
                    // console.log(`${_module} addNewRelations crLabel`, cr.label)
                    // console.log(`${_module} addNewRelations crLabel`, relation[0][0])
                    if (cr.label === relation[0][0]) {
                        cr.sublabel = "added"
                    }
                })
            })
        }

        // await ctx.set("gpt_recent_results", gpt_recent)
        workspace["gpt_recent_results"] = gpt_recent
        let updatedFlow = await updateWorkspaceContext(req.body.activeWorkspace, workspace)
        // await ctx.set(req.body.activeWorkspace, workspace)
        // updateFlow(flowId, flow, "")
        delete seenNodes
        res.status(200).send({
            gpt_results: "ok",
            nodesToAdd: nodesToAdd,
            linksToAdd: linksToAdd,
            updatedFlow: updatedFlow
        })
    } catch (exception) {
        console.log(`${_module} addNewRelations exception`, exception)
        res.status(500).send({ error: exception })
    }
}

/**
 * 
 */
async function storeGptInfo(req, res) {
    console.log(`${_module} =================== storeGptInfo ===================`)
    try {
        let flow = req.body
        // match the 
        let match_gpt_info = `match $gpt_info isa gpt_info, has nrid \"${flow.id}\";`
        let match_gpt_info_opts = {
            "db": "causeway-repo",
            "query": match_gpt_info,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ"
        }
        let gpt_info_query_result = await typedbApi.executeQuery(match_gpt_info_opts)
        await typedbApi.close_transaction(match_gpt_info_opts.transaction_type)
        let update = gpt_info_query_result.length > 0 ? true : false

        let insert_gpt_info = `insert $gpt_info isa gpt_info, has nrid \"${flow.id}\"`
        let gptKeys = ["gpt_prompt", "gpt_research_question", "gpt_api_key", "gpt_api_org", "gpt_recent_results"]
        for await (let key of gptKeys) {
            if (flow.hasOwnProperty(key)) {
                console.log(`${_module} storeGptInfo has key ${key}`)
                let item = typeof flow[key] === "string" ? flow[key] : JSON.stringify(flow[key])
                item = item.replace(/"/g, "'")
                insert_gpt_info += `, has ${key} \"${item}\"`
            }
        }
        insert_gpt_info.slice(0, -2)
        insert_gpt_info += ";"
        // update [ typedb: match-delete-insert ] or insert [typed: insert]
        if (update) {
            console.log(`${_module} storeGptInfo update ${update}`)
            // get transaction 
            let delete_gpt_info = match_gpt_info + `\ndelete $gpt_info isa gpt_info;\n`
            let opts = {
                "db": "causeway-repo",
                "query": delete_gpt_info,
                "query_type": "delete",
                "session_type": "DATA",
                "transaction_type": "WRITE"
            }
            console.log(`${_module} storeGptInfo update update_gpt_info ${delete_gpt_info}`)
            let query_result = await typedbApi.executeQuery(opts)
            // get transaction 
            opts = {
                "db": "causeway-repo",
                "query": insert_gpt_info,
                "query_type": "insert",
                "session_type": "DATA",
                "transaction_type": "WRITE"
            }
            console.log(`${_module} storeGptInfo update update_gpt_info ${insert_gpt_info}`)
            query_result = await typedbApi.executeQuery(opts)
        } else {
            console.log(`${_module} storeGptInfo update ${update}`)
            console.log(`${_module} storeGptInfo final insert_gpt_info \n ${insert_gpt_info}`)
            // get transaction 
            let opts = {
                "db": "causeway-repo",
                "query": insert_gpt_info,
                "query_type": "insert",
                "session_type": "DATA",
                "transaction_type": "WRITE"
            }
            let query_result = await typedbApi.executeQuery(opts)
        }
        res.send(200).status("Success in storing gpt info to TypeDB")
    } catch (exception) {
        console.log(`${_module} storeGptInfo throwing error`)
        res.status(500).send({ error: exception })
    }
}
